def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my_last, opp_last = history[-1]

    # Check if opponent ever retaliated to one of our defections
    retaliated = False
    for i in range(n - 1):
        if history[i][0] == 'D' and history[i+1][1] == 'D':
            retaliated = True
            break

    # If opponent defected last round, punish
    if opp_last == 'D':
        if my_last == 'D':
            # Mutual defection: occasionally try to restore cooperation
            if rng.random() < 0.3:
                return 'C'
            return 'D'
        else:
            return 'D'

    # Opponent cooperated last round
    if my_last == 'D':
        # We defected, opponent cooperated: forgive and return to cooperation
        return 'C'

    # Both cooperated last round
    # If opponent has retaliated before, play safe: cooperate until last round, then defect
    if retaliated:
        if n >= 99:
            return 'D'
        return 'C'

    # Opponent has not retaliated to our defections
    my_defects = sum(1 for a, b in history if a == 'D')

    # Early probing: if we haven't defected yet, probe at round 20
    if my_defects == 0:
        if n == 20:
            return 'D'
        return 'C'

    # Endgame exploitation if opponent is forgiving (no retaliation observed)
    if n >= 90:
        # Defect on even n (rounds 91, 93, 95, 97, 99) and on round 100 (n=99)
        if n % 2 == 0 or n == 99:
            return 'D'
        return 'C'

    return 'C'
